window.kbPageData["views/entry/k-39dd0a8ce74c7700"] = {"key":"entry/k-39dd0a8ce74c7700","state":{"route":"entry/k-39dd0a8ce74c7700"},"node":{"id":"k-39dd0a8ce74c7700","mode":"k","title":"持续深化重点领域改革","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"充分激发各类经营主体活力。坚持和落实“两个毫不动摇”①。制定和实施进一步深化\n国资国企改革方案，推进国有经济布局优化和结构调整。完善民营经济②促进法配套法规政\n策，从法律和制度上保障平等使用生产要素、公平参与市场竞争、有效保护合法权益。完\n善中国特色现代企业制度③。大力弘扬企业家精神④，促进年轻一代…","sources":[{"id":"b9701ba6ba0ed64a","label":"持续深化重点领域改革","topic":"年度政府工作","category":"时政","text":"充分激发各类经营主体活力。坚持和落实“两个毫不动摇”①。制定和实施进一步深化\n国资国企改革方案，推进国有经济布局优化和结构调整。完善民营经济②促进法配套法规政\n策，从法律和制度上保障平等使用生产要素、公平参与市场竞争、有效保护合法权益。完\n善中国特色现代企业制度③。大力弘扬企业家精神④，促进年轻一代企业家健康成长。推动\n平台企业和平台内经营者、劳动者共赢发展。分型分类精准帮扶个体工商户发展。下更大力\n气解决拖欠企业账款问题。持续打造一流营商环境，更好支持企业安心经营、高质量发展。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"90a77577d89da6a9","label":"持续深化重点领域改革","topic":"年度政府工作","category":"时政","text":"（四）持续深化重点领域改革。围绕构建高水平社会主义市场经济体制①，强化改革攻\n坚，深入破除体制机制障碍，增强高质量发展动力活力。\n纵深推进全国统一大市场建设②。制定全国统一大市场建设条例。完善统计、财税、考\n核等制度，规范地方政府经济促进行为，出台地方政府招商引资鼓励和禁止事项清单，规范\n税收优惠、财政补贴政策。深化招标投标体制机制改革。加强反垄断、反不正当竞争，强化\n公平竞争审查刚性约束，综合运用产能调控、标准引领、价格执法、质量监管等手段，深入\n整治“内卷式”竞争③，营造良好市场生态。深化要素市场化配置综合改革试点，将更多符\n合条件的地区纳入试点范围。稳步推进公用事业和公共服务价格改革。","source":{"doc":"6cbfb01fe723bba64b75","first":28,"last":28,"page":28,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"caf62967f18664d2","label":"持续深化重点领域改革","topic":"年度政府工作","category":"时政","text":"推进财税金融体制改革。加大财政资源和预算统筹力度，提高国有资本①收益收取比例。\n加强财政科学管理，深化零基预算②改革，进一步扩大中央部门试点范围。健全地方税体系，\n拓展地方税源。调整优化消费税征税范围、税率，并推进部分品目征收环节后移。规范金融\n机构竞争秩序，深入推进地方中小金融机构减量提质。持续深化资本市场投融资综合改革，\n进一步健全中长期资金入市机制，完善投资者保护制度，拓展私募股权和创投基金退出渠道，\n提高直接融资、股权融资比重。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-39dd0a8ce74c7700":[]}};
